#include <chrono>
#include <iomanip>
#include <iostream>
#include <type_traits>  // for std::is_same_v

#include "Halide.h"

// include common Polybench definitions (NI, NJ, NK, NL, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    // ------------------------------------------------------------------
    // Scheduling for initialization
    //
    // These init Funcs are simple and embarrassingly parallel. We:
    //  - parallelize across the outer (row) dimension
    //  - vectorize across the innermost (contiguous) dimension
    // This makes initialization reasonably fast even for large matrices.
    // ------------------------------------------------------------------
    constexpr int vec_width_init = 8;  // conservative, Halide will scalarize tails as needed

    // For A(k, i): k is contiguous (x), i is outer (y)
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(k, vec_width_init);

    // For B(j, k): j is contiguous (x), k is outer (y)
    init_B
        .compute_root()
        .parallel(k)
        .vectorize(j, vec_width_init);

    // For C(l, j): l is contiguous (x), j is outer (y)
    init_C
        .compute_root()
        .parallel(j)
        .vectorize(l, vec_width_init);

    // For D(l, i): l is contiguous (x), i is outer (y)
    init_D
        .compute_root()
        .parallel(i)
        .vectorize(l, vec_width_init);

    // Compute into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //   - Preserve the original numerical semantics.
    //   - Exploit parallelism across the row dimension (i).
    //   - Vectorize across the innermost, contiguous dimension (j for tmp,
    //     l for D), for good memory bandwidth.
    //   - Tile the contiguous dimension to balance locality and vectorization.
    //
    // Layout recap:
    //   tmp(j, i): j is dim 0 (contiguous), i is dim 1
    //   D(l, i):   l is dim 0 (contiguous), i is dim 1
    //
    // We use:
    //   - parallel(i) on both tmp and D to leverage multiple cores
    //   - vectorize along j (for tmp) and l (for D)
    //   - split j and l into tiles to get reasonable working-set sizes
    // ------------------------------------------------------------------------

    // Choose a reasonable vector width based on the element type:
    //   - 2-wide for double (128-bit SSE)
    //   - 4-wide for float  (128-bit SSE)
    //   - 4 as a conservative default for other types.
    constexpr int vec_width =
        std::is_same_v<num_t, double> ? 2 :
        std::is_same_v<num_t, float>  ? 4 :
                                        4;

    // Tile sizes along the contiguous dimensions (multiples of vec_width).
    constexpr int tile_j = 64;
    constexpr int tile_l = 64;

    Var j_outer("j_outer"), j_inner("j_inner");
    Var l_outer("l_outer"), l_inner("l_inner");

    // ---- Schedule for tmp_func: tmp(j, i) = sum_k alpha * A(k, i) * B(j, k) ----
    //
    // We keep i as the outer parallel dimension and operate on tiles of j.
    // Within each tile, we vectorize over j_inner. The reduction over k_AB
    // is innermost (just outside j_inner) so that:
    //   for i (parallel)
    //     for j_outer
    //       for k_AB
    //         for j_inner (vectorized)
    //           tmp(j, i) += ...
    //
    // This yields contiguous writes to tmp and contiguous reads in B(j,k)
    // along j, while reusing A(k,i) across all j in the tile.

    tmp_func
        .compute_root()
        .split(j, j_outer, j_inner, tile_j)
        .reorder(j_inner, j_outer, i)      // i outer, then j tiles, then j_inner
        .parallel(i)
        .vectorize(j_inner, vec_width);

    tmp_func.update()
        .split(j, j_outer, j_inner, tile_j)
        .reorder(j_inner, k_AB, j_outer, i) // i outer, then j_outer, then k_AB, then j_inner
        .parallel(i)
        .vectorize(j_inner, vec_width);

    // ---- Schedule for D_func: D(l, i) = beta * D(l, i) + sum_j tmp(j, i) * C(l, j) ----
    //
    // Similar strategy: parallelize across i (rows), tile and vectorize across l (columns).
    // The loop structure for the update becomes:
    //   for i (parallel)
    //     for l_outer
    //       for k_DC
    //         for l_inner (vectorized)
    //           D(l, i) += tmp(k_DC, i) * C(l, k_DC);

    D_func
        .compute_root()
        .split(l, l_outer, l_inner, tile_l)
        .reorder(l_inner, l_outer, i)      // i outer, then l tiles, then l_inner
        .parallel(i)
        .vectorize(l_inner, vec_width);

    D_func.update()
        .split(l, l_outer, l_inner, tile_l)
        .reorder(l_inner, k_DC, l_outer, i) // i outer, then l_outer, then k_DC, then l_inner
        .parallel(i)
        .vectorize(l_inner, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
