    // Scheduling for initialization
    //
    // All four initializations are embarrassingly parallel and have
    // unit-stride in their first coordinate. We:
    //  - make the first coordinate the vectorized dimension
    //  - parallelize across the second dimension
    // Vector width 8 is a reasonable default on modern x86 (it maps to
    // 256 bits for float and 512 bits for smaller types; Halide will
    // handle tails if the extent is not a multiple of 8).
    // --------------------------------------------------------------------
    const int vec = 8;

    init_A
        .compute_root()
        .reorder(k, i)   // inner: k (contiguous), outer: i
        .vectorize(k, vec)
        .parallel(i);

    init_B
        .compute_root()
        .reorder(j, k)   // inner: j (contiguous), outer: k
        .vectorize(j, vec)
        .parallel(k);

    init_C
        .compute_root()
        .reorder(l, j)   // inner: l (contiguous), outer: j
        .vectorize(l, vec)
        .parallel(j);

    init_D
        .compute_root()
        .reorder(l, i)   // inner: l (contiguous), outer: i
