    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // kept for symmetry with C version (not used directly)

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp        (first dimension)
    //   l -> column index for D          (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i)      corresponds to tmp[i][j]
    //   A_param(k, i)  corresponds to A[i][k]
    //   B_param(j, k)  corresponds to B[k][j]
    //   C_param(l, j)  corresponds to C[j][l]
    //   D_param(l, i)  corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");  // over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");  // over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    // - Parallelize across rows i (outer dimension) to exploit many cores.
    // - Vectorize across the fast-varying dimensions (j for tmp, l for D)
    //   to get good SIMD utilization.
    // - Order loops to improve data locality:
    //     * For tmp: keep j innermost so B and tmp are accessed contiguously,
    //       while reusing A(k,i) across j.
    //     * For D: iterate i outer, then k, then l; this reuses tmp(i,k)
    //       across l and keeps C and D accesses contiguous in l.
    // ------------------------------------------------------------------------

    // Choose a SIMD width appropriate for the host and num_t.
    Target target = get_host_target();
    int vec_width = natural_vector_size<num_t>(target);
    if (vec_width < 1) vec_width = 1;

    Var j_outer("j_outer"), j_inner("j_inner");
    Var l_outer("l_outer"), l_inner("l_inner");

    // ---- Schedule for tmp_func ----
    //
    // Pure step: initialize tmp(j,i) = 0.
    //   Parallelize across i (rows) and vectorize across j (columns).
    tmp_func
        .compute_root()
        .reorder(j, i)                  // i outer, j inner (row-major over tmp)
        .split(j, j_outer, j_inner, vec_width)
        .parallel(i)
        .vectorize(j_inner);

    // Update step: tmp(j,i) += alpha*A(k,i)*B(j,k)
    //
    // We want loops:
    //   for i
    //     for k
    //       for j (contiguous, vectorized)
    //
    // So we reorder as (j, k_AB, i), then split j for vectorization,
    // and parallelize over i.
    tmp_func.update()
        .reorder(j, k_AB, i);

    tmp_func.update()
        .split(j, j_outer, j_inner, vec_width)
        .parallel(i)
        .vectorize(j_inner);

    // ---- Schedule for D_func ----
    //
    // Pure step: D(l,i) = beta * D_param(l,i)
    //   Parallelize across i and vectorize across l.
    D_func
        .compute_root()
        .reorder(l, i)                  // i outer, l inner
        .split(l, l_outer, l_inner, vec_width)
        .parallel(i)
        .vectorize(l_inner);

    // Update step: D(l,i) += sum_k tmp(k,i) * C(l,k)
    //
    // Desired loop order:
    //   for i
    //     for k_DC
    //       for l (contiguous, vectorized)
    //
    // This reuses tmp(k_DC,i) across l and keeps C(l,k_DC)/D(l,i)
    // accesses contiguous in l.
    D_func.update()
        .reorder(l, k_DC, i);

    D_func.update()
        .split(l, l_outer, l_inner, vec_width)
        .parallel(i)
        .vectorize(l_inner);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
